diff --git a/src/server.js b/src/server.js
index 0969320..7aaadd0 100644
--- a/src/server.js
+++ b/src/server.js
@@ -13,7 +13,27 @@ export function createApp(inventory = Inventory.fromFile()) {

   router.get('/health', () => ({ status: 200, body: { status: 'ok' } }))

-  router.get('/books', () => ({ status: 200, body: inventory.list() }))
+  router.get('/books', async ({ query }) => {
+  const page = parseInt(query.get('page')) || 1;
+  const limit = Math.min(parseInt(query.get('limit')) || 20, 50);
+  const totalBooks = inventory.list().length;
+
+  // Validation
+  if (page < 1 || limit < 1 || isNaN(page) || isNaN(limit)) {
+    return { status: 400, body: { error: 'Bad Request' } };
+  }
+
+  const start = (page - 1) * limit;
+  const end = start + limit;
+
+  // Clamping the page if it exceeds the total number of pages
+  if (start >= totalBooks) {
+    return { status: 200, headers: { 'X-Total-Count': totalBooks }, body: [] };
+  }
+
+  const paginatedBooks = inventory.list().slice(start, end);
+  return { status: 200, headers: { 'X-Total-Count': totalBooks }, body: paginatedBooks };
+});

