diff --git a/test/pagination.test.js b/test/pagination.test.js
new file mode 100644
index 0000000..5e5cdcf
--- /dev/null
+++ b/test/pagination.test.js
@@ -0,0 +1,31 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { createApp } from '../src/server.js';
+import { Inventory } from '../src/inventory.js';
+
+const app = () => createApp(Inventory.fromFile());
+
+// Test for pagination
+
+test('GET /books paginated results', async () => {
+  const res1 = await app()({ method: 'GET', url: '/books?page=1&limit=5' });
+  assert.equal(res1.status, 200);
+  assert.equal(res1.body.length, 5);
+
+  const res2 = await app()({ method: 'GET', url: '/books?page=2&limit=5' });
+  assert.equal(res2.status, 200);
+  assert.equal(res2.body.length, 3);
+
+  const res3 = await app()({ method: 'GET', url: '/books?page=3&limit=5' });
+  assert.equal(res3.status, 200);
+  assert.equal(res3.body.length, 0);
+
+  const resInvalidPage = await app()({ method: 'GET', url: '/books?page=-1' });
+  assert.equal(resInvalidPage.status, 400);
+  assert.deepEqual(resInvalidPage.body, { error: 'Bad Request' });
+
+  const resInvalidLimit = await app()({ method: 'GET', url: '/books?limit=100' });
+  assert.equal(resInvalidLimit.status, 200);
+  assert.equal(resInvalidLimit.body.length, 8);
+  assert.equal(resInvalidLimit.headers['X-Total-Count'], '8');
+});
